ids=["LY-312","LY-314","LY-315","LY-318","LY-319","LY-320","LY-322","LY-323","LY-324","LY-325","LY-328","LY-329","LY-330","LY-331","LY-332","LY-333","LY-335","LY-336","LY-338","LY-339"]
assert set(P)==set(ids) and len(P)==len(ids)==20, (set(ids)-set(P))
for cid in ids:
    with open(os.path.join(BASE,cid+".json"),"w",encoding="utf-8") as f:
        json.dump(P[cid],f,ensure_ascii=False,indent=2)
# 回讀校驗
cnt=0
for cid in ids:
    d=json.load(open(os.path.join(BASE,cid+".json"),encoding="utf-8"))
    assert d["case_id"]==cid
    for k in ("case_id","prediction_text","basis","confidence","trigger"): assert k in d, (cid,k)
    for k in ("changed_main","reserve_used","disputed","reason"): assert k in d["trigger"], (cid,k)
    assert isinstance(d["confidence"],(int,float)) and 0<=d["confidence"]<=1
    cnt+=1
assert cnt==len(ids)
cm=sum(v["trigger"]["changed_main"] for v in P.values()); ru=sum(v["trigger"]["reserve_used"] for v in P.values()); di=sum(v["trigger"]["disputed"] for v in P.values())
print(f"WROTE {cnt} files; changed_main={cm} reserve_used={ru} disputed={di}")
